// ---------------------------------------------------------------
// Reemplazar estos tres valores antes de activar el workflow.
// __RTDB_URL__    sin barra final, ej. https://xxxx-default-rtdb.firebaseio.com
// __RTDB_SECRET__ el secreto de la base en tiempo real
// __TOKEN_ODOO__  el mismo token configurado en Odoo (largo y aleatorio)
// ---------------------------------------------------------------
const RTDB = '__RTDB_URL__';
const SECRETO = '__RTDB_SECRET__';
const TOKEN = '__TOKEN_ODOO__';

const crudo = $input.first().json;
const entrada = crudo.body || crudo;

const token = String(entrada.token || '');
const accion = String(entrada.accion || 'autorizar');
const orderId = parseInt(entrada.orderId, 10);

let error = '';
if (token !== TOKEN) {
  error = 'Token invalido.';
} else if (!Number.isInteger(orderId) || orderId <= 0) {
  error = 'orderId invalido.';
} else if (accion !== 'consultar' && accion !== 'autorizar') {
  error = 'Accion desconocida.';
}

// approvedBy y reason salen impresos en el ticket, que mide 48 columnas.
// Se recortan para que el encabezado de COPIA no se vuelva ilegible.
return [{
  json: {
    valido: error === '',
    error,
    accion,
    orderId: Number.isInteger(orderId) ? orderId : 0,
    approvedBy: String(entrada.approvedBy || '').slice(0, 90),
    reason: String(entrada.reason || '').slice(0, 120),
    urlLedger: RTDB + '/print_ledger/' + orderId + '.json?auth=' + SECRETO,
    urlAprobacion: RTDB + '/print_reprint_approvals/' + orderId + '.json?auth=' + SECRETO
  }
}];

const prep = $('Preparar').first().json;
const datos = $input.first().json;

if (prep.accion === 'consultar') {
  // Firebase devuelve null cuando la orden nunca se imprimio.
  const ledger = (datos && typeof datos === 'object') ? datos : {};
  return [{
    json: {
      ok: true,
      accion: 'consultar',
      orderId: prep.orderId,
      copies: Number(ledger.copies || 0),
      status: ledger.status || '',
      orderName: ledger.orderName || ''
    }
  }];
}

// La escritura de la aprobacion no imprime nada por si sola: el agente escucha
// /print_reprint_approvals y consume el token dentro de su propia transaccion.
return [{
  json: {
    ok: true,
    accion: 'autorizar',
    orderId: prep.orderId,
    approvedBy: prep.approvedBy
  }
}];
